    border-radius: 7px;
    cursor: pointer;
    transition: border-color 120ms ease, color 120ms ease, background 120ms ease;
}

.marketing-report-pagination__btn:hover:not(:disabled) {
    border-color: rgba(210, 165, 80, 0.55);
    color: rgba(255, 225, 170, 0.98);
    background: rgba(210, 165, 80, 0.08);
}

.marketing-report-pagination__btn:focus-visible {
    outline: 2px solid rgba(210, 165, 80, 0.7);
    outline-offset: 2px;
}

.marketing-report-pagination__btn:disabled {
    opacity: 0.38;
    cursor: not-allowed;
}

.marketing-report-pagination__pages {
    display: flex;
    gap: 4px;
    list-style: none;
    margin: 0;
    padding: 0;
}

.marketing-report-pagination__page {
    min-width: 34px;
    padding: 7px 10px;
    font-size: 0.8rem;
    font-family: inherit;
    color: rgba(225, 225, 230, 0.88);
    background: transparent;
    border: 1px solid transparent;
    border-radius: 7px;
    cursor: pointer;
    transition: background 120ms ease, border-color 120ms ease, color 120ms ease;
}

.marketing-report-pagination__page:hover {
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 225, 170, 0.98);
}

.marketing-report-pagination__page:focus-visible {
    outline: 2px solid rgba(210, 165, 80, 0.7);
    outline-offset: 2px;
}

.marketing-report-pagination__page--active,
.marketing-report-pagination__page--active:hover {
    color: rgba(20, 18, 12, 0.96);
    background: linear-gradient(155deg, rgba(216, 181, 106, 0.96) 0%, rgba(184, 141, 60, 0.96) 100%);
    border-color: rgba(192, 159, 83, 0.65);
    font-weight: 600;
    cursor: default;
}

.marketing-report-pagination__gap {
    padding: 7px 2px;
    color: rgba(160, 160, 170, 0.7);
    -webkit-user-select: none;
    user-select: none;
}

.marketing-report-pagination__meta {
    flex-basis: 100%;
    margin-top: 2px;
    font-size: 0.76rem;
    line-height: 1.4;
    color: rgba(180, 180, 190, 0.86);
    text-align: center;
}

.marketing-report-pagination__meta strong {
    color: rgba(230, 230, 235, 0.95);
    font-weight: 600;
}

@media (min-width: 720px) {
    .marketing-report-pagination__meta {
        flex-basis: auto;
        margin-top: 0;
        margin-left: 12px;
        text-align: left;
    }
}

/*
 * --- Ad-platform reconciliation panel ----------------------------------
 *
 * Sits between the KPI grid and the chart strip. Inputs stack responsively;
 * result cards flow in a 3–4 column grid on wide screens, collapsing to a
 * single column on phones. The "good" and "warn" tones match the rest of
 * the dashboard's palette (green accents for visibility, gold/amber for the
 * invisible-gap card).
 */

.marketing-reconciliation {
    margin: 0 0 28px;
    padding: 18px 18px 20px;
    border-radius: 14px;
    border: 1px solid rgba(192, 159, 83, 0.24);
    background: linear-gradient(
        155deg,
        rgba(192, 159, 83, 0.08) 0%,
        rgba(0, 0, 0, 0.22) 65%
    );
}

.marketing-reconciliation__header {
    margin-bottom: 14px;
}

.marketing-reconciliation__inputs {
    display: grid;
    grid-template-columns: 1.2fr 1fr 1fr auto;
    gap: 12px 14px;
    align-items: end;
    margin-bottom: 8px;
}

@media (max-width: 900px) {
    .marketing-reconciliation__inputs {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 540px) {
    .marketing-reconciliation__inputs {
        grid-template-columns: 1fr;
    }
}

.marketing-reconciliation__field {
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 0;
}

.marketing-reconciliation__field-label {
    font-size: 0.74rem;
    font-weight: 600;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: rgba(195, 195, 205, 0.86);
}

.marketing-reconciliation__input,
.marketing-reconciliation__select {
    width: 100%;
    padding: 9px 11px;
    font-size: 0.88rem;
    font-family: inherit;
    color: rgba(245, 243, 238, 0.98);
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 8px;
    outline: none;
    transition:
        border-color 120ms ease,
        background 120ms ease;
}

.marketing-reconciliation__input:focus,
.marketing-reconciliation__select:focus {
    border-color: rgba(192, 159, 83, 0.6);
    background: rgba(0, 0, 0, 0.38);
}

.marketing-reconciliation__money {
    display: flex;
    gap: 6px;
    min-width: 0;
}

.marketing-reconciliation__input--money {
    flex: 1;
    min-width: 0;
}

.marketing-reconciliation__select--currency {
    flex: 0 0 auto;
    width: 88px;
}

.marketing-reconciliation__actions {
    display: flex;
    justify-content: flex-end;
    align-items: flex-end;
}

.marketing-reconciliation__clear {
    padding: 9px 14px;
    font-size: 0.82rem;
    font-family: inherit;
    color: rgba(215, 215, 220, 0.94);
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 8px;
    cursor: pointer;
    transition:
        border-color 120ms ease,
        color 120ms ease;
}

.marketing-reconciliation__clear:hover {
    border-color: rgba(210, 165, 80, 0.5);
    color: rgba(255, 225, 170, 0.98);
}

.marketing-reconciliation__window-hint {
    margin: 2px 0 16px;
    font-size: 0.76rem;
    line-height: 1.5;
    color: rgba(160, 160, 170, 0.88);
}

.marketing-reconciliation__empty {
    padding: 18px 16px;
    font-size: 0.88rem;
    line-height: 1.55;
    color: rgba(185, 185, 195, 0.92);
    border: 1px dashed rgba(192, 159, 83, 0.28);
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.12);
}

.marketing-reconciliation__empty strong {
    color: rgba(245, 243, 238, 0.98);
    font-weight: 600;
}

/*
 * Result grid: 4-up on wide desktops (three reconciliation cards + cost
 * card when spend is entered), graceful fallback to 2-up and 1-up.
 */
.marketing-reconciliation__results {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 12px;
    margin-top: 4px;
}

.marketing-reconciliation__result {
    padding: 14px 14px 15px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(255, 255, 255, 0.035);
}

.marketing-reconciliation__result--good {
    border-color: rgba(140, 200, 130, 0.35);
    background: linear-gradient(
        155deg,
        rgba(140, 200, 130, 0.12) 0%,
        rgba(0, 0, 0, 0.25) 60%
    );
}

.marketing-reconciliation__result--warn {
    border-color: rgba(210, 165, 80, 0.45);
    background: linear-gradient(
        155deg,
        rgba(210, 165, 80, 0.14) 0%,
        rgba(0, 0, 0, 0.25) 60%
    );
}

.marketing-reconciliation__result-title {
    margin: 0 0 6px;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: rgba(195, 195, 205, 0.92);
}

.marketing-reconciliation__result--good .marketing-reconciliation__result-title {
    color: rgba(175, 220, 165, 0.95);
}

.marketing-reconciliation__result--warn .marketing-reconciliation__result-title {
    color: rgba(235, 200, 140, 0.95);
}

.marketing-reconciliation__result-headline {
    margin: 0 0 6px;
    font-size: 1.3rem;
    font-weight: 600;
    line-height: 1.25;
    color: rgba(245, 243, 238, 0.98);
}

.marketing-reconciliation__result-detail {
    margin: 0;
    font-size: 0.82rem;
    line-height: 1.5;
    color: rgba(195, 195, 205, 0.9);
}

.marketing-reconciliation__result-sub {
    margin: 8px 0 0;
    padding-top: 8px;
    font-size: 0.76rem;
    line-height: 1.5;
    color: rgba(170, 170, 180, 0.86);
    border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/*
 * --- Reconciliation: save / snapshots --------------------------------
 *
 * The save button shares the actions slot with "Clear inputs" and gets
 * the gold accent treatment so it reads as the primary CTA. The
 * snapshots list is a collapsible details-style block with a compact
 * table — wide enough to be useful, narrow enough not to dominate.
 */

.marketing-reconciliation__actions {
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
}

@media (min-width: 901px) {
    .marketing-reconciliation__actions {
        flex-direction: row;
        align-items: flex-end;
        justify-content: flex-end;
    }
}

.marketing-reconciliation__save {
    padding: 9px 16px;
    font-size: 0.84rem;
    font-weight: 600;
    font-family: inherit;
    color: rgba(20, 18, 12, 0.96);
    background: linear-gradient(155deg, #d8b56a 0%, #b88d3c 100%);
    border: 1px solid rgba(192, 159, 83, 0.7);
    border-radius: 8px;
    cursor: pointer;
    transition:
        transform 80ms ease,
        box-shadow 120ms ease,
        opacity 120ms ease;
}

.marketing-reconciliation__save:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 6px 14px -8px rgba(210, 165, 80, 0.6);
}

.marketing-reconciliation__save:disabled {
    cursor: not-allowed;
    opacity: 0.45;
}

.marketing-reconciliation__snapshots {
    margin-top: 22px;
    padding-top: 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.marketing-reconciliation__snapshots-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
}

.marketing-reconciliation__snapshots-toggle {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px 7px 6px;
    margin-left: -6px;
    font-size: 0.86rem;
    font-weight: 600;
    font-family: inherit;
    color: rgba(235, 233, 228, 0.96);
    background: transparent;
    border: 1px solid transparent;
    border-radius: 8px;
    cursor: pointer;
    transition: background 120ms ease;
}

.marketing-reconciliation__snapshots-toggle:hover {
    background: rgba(255, 255, 255, 0.04);
}

.marketing-reconciliation__snapshots-count {
    display: inline-flex;
    min-width: 22px;
    height: 22px;
    padding: 0 7px;
    align-items: center;
    justify-content: center;
    font-size: 0.74rem;
    font-weight: 600;
    color: rgba(255, 225, 170, 0.98);
    background: rgba(210, 165, 80, 0.18);
    border: 1px solid rgba(210, 165, 80, 0.45);
    border-radius: 999px;
}

.marketing-reconciliation__snapshots-actions {
    display: inline-flex;
    gap: 8px;
}

.marketing-reconciliation__snapshots-export,
.marketing-reconciliation__snapshots-clear {
    padding: 7px 12px;
    font-size: 0.78rem;
    font-family: inherit;
    color: rgba(225, 225, 230, 0.94);
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 7px;
    cursor: pointer;
    transition:
        border-color 120ms ease,
        color 120ms ease,
        background 120ms ease;
}

.marketing-reconciliation__snapshots-export:hover {
    border-color: rgba(210, 165, 80, 0.55);
    color: rgba(255, 225, 170, 0.98);
}

.marketing-reconciliation__snapshots-clear:hover {
    border-color: rgba(220, 110, 110, 0.55);
    color: rgba(245, 175, 175, 0.98);
}

.marketing-reconciliation__snapshots-empty {
    margin: 14px 0 0;
    padding: 14px 14px;
    font-size: 0.84rem;
    line-height: 1.55;
    color: rgba(180, 180, 190, 0.9);
    border: 1px dashed rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.1);
}

.marketing-reconciliation__snapshots-empty strong {
    color: rgba(245, 243, 238, 0.98);
    font-weight: 600;
}

.marketing-reconciliation__snapshots-table-wrap {
    margin-top: 14px;
    overflow-x: auto;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
}

.marketing-reconciliation__snapshots-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.82rem;
    color: rgba(225, 225, 230, 0.94);
}

.marketing-reconciliation__snapshots-table thead th {
    padding: 9px 10px;
    text-align: left;
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(180, 180, 190, 0.92);
    background: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    white-space: nowrap;
}

.marketing-reconciliation__snapshots-table tbody td {
    padding: 9px 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    vertical-align: top;
}

.marketing-reconciliation__snapshots-table tbody tr:last-child td {
    border-bottom: none;
}

.marketing-reconciliation__snapshots-table tbody tr:hover {
    background: rgba(255, 255, 255, 0.025);
}

.marketing-reconciliation__snapshots-table .num {
    text-align: right;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

.marketing-reconciliation__snapshots-metric,
.marketing-reconciliation__snapshots-sub {
    color: rgba(160, 160, 170, 0.86);
    font-size: 0.74rem;
}

.marketing-reconciliation__snapshots-delete {
    padding: 2px 8px;
    font-size: 1rem;
    line-height: 1;
    font-family: inherit;
    color: rgba(200, 200, 210, 0.7);
    background: transparent;
    border: 1px solid transparent;
    border-radius: 6px;
    cursor: pointer;
    transition:
        color 120ms ease,
        border-color 120ms ease,
        background 120ms ease;
}

.marketing-reconciliation__snapshots-delete:hover {
    color: rgba(245, 175, 175, 0.98);
    border-color: rgba(220, 110, 110, 0.45);
    background: rgba(220, 110, 110, 0.08);
}

/*
 * --- Reconciliation: over-count & caption ----------------------------
 *
 * "Over-count" = the scope's attributed consents exceed the reported
 * clicks/sessions from the ad platform (multi-session visits, pre-
 * consented returns, UTM-tagged URLs shared beyond the ad). The row is
 * lightly tinted amber, the Reported cell carries a compact badge, and
 * the in-cell share label is capped at "100%+" so the math stays
 * readable.
 */
.marketing-reconciliation__snapshots-caption {
    margin: 0 0 10px;
    font-size: 0.78rem;
    line-height: 1.55;
    color: rgba(180, 180, 190, 0.86);
}

.marketing-reconciliation__over-count-badge {
    display: inline-flex;
    align-items: center;
    margin-left: 8px;
    padding: 1px 7px;
    font-size: 0.66rem;
    font-weight: 600;
    letter-spacing: 0.03em;
    text-transform: lowercase;
    color: rgba(255, 225, 170, 0.98);
    background: rgba(210, 165, 80, 0.18);
    border: 1px solid rgba(210, 165, 80, 0.45);
    border-radius: 999px;
    vertical-align: middle;
    white-space: nowrap;
}

.marketing-reconciliation__over-count-badge--inline {
    margin: 0 4px;
}

.marketing-reconciliation__snapshots-row--overcount {
    background: rgba(210, 165, 80, 0.05);
    box-shadow: inset 3px 0 0 0 rgba(210, 165, 80, 0.45);
}

.marketing-reconciliation__snapshots-row--overcount:hover {
    background: rgba(210, 165, 80, 0.09);
}

/*
 * --- Reconciliation: platform filter note ----------------------------
 *
 * The filter note sits between the inputs and the result cards. When
 * the filter is active and matched, it shows the coverage + matched
 * utm_source values. When active and empty, it swaps to a warn tone
 * prompting the user to fix their UTM tagging or switch to "Other".
 */

.marketing-reconciliation__filter-note {
    margin: 0 0 14px;
    padding: 10px 14px;
    font-size: 0.82rem;
    line-height: 1.55;
    color: rgba(215, 215, 220, 0.92);
    background: rgba(0, 0, 0, 0.18);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
}

.marketing-reconciliation__filter-note p {
    margin: 0;
}

.marketing-reconciliation__filter-note code {
    padding: 1px 6px;
    font-size: 0.78rem;
    color: rgba(255, 225, 170, 0.95);
    background: rgba(210, 165, 80, 0.1);
    border: 1px solid rgba(210, 165, 80, 0.25);
    border-radius: 5px;
}

.marketing-reconciliation__filter-note--empty {
    color: rgba(245, 210, 170, 0.96);
    background: linear-gradient(
        155deg,
        rgba(210, 130, 80, 0.15) 0%,
        rgba(0, 0, 0, 0.22) 65%
    );
    border-color: rgba(220, 140, 90, 0.45);
}

/*
 * --- Suggestions strip ------------------------------------------------
 *
 * Sits between the KPI grid and the reconciliation panel. Visually quieter
 * than the KPI cards (no large numbers) so it reads as a *next move*
 * footnote, not as another metric. Severity is encoded in (1) a chip in
 * the card head, (2) a coloured left border, and (3) a faint background
 * tint — three independent cues so colour-blind readers still see the
 * priority distinction.
 */

.marketing-suggestions {
    margin: 0 0 28px;
    padding: 16px 18px 18px;
    border-radius: 14px;
    background: linear-gradient(
        155deg,
        rgba(255, 255, 255, 0.03) 0%,
        rgba(255, 255, 255, 0.01) 100%
    );
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.marketing-suggestions__head {
    margin: 0 0 12px;
}

.marketing-suggestions__title {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: rgba(240, 232, 210, 0.95);
}

.marketing-suggestions__hint {
    margin: 4px 0 0;
    font-size: 0.78rem;
    line-height: 1.45;
    color: rgba(165, 165, 175, 0.9);
    max-width: 56rem;
}

.marketing-suggestions__list {
    display: grid;
    gap: 10px;
    list-style: none;
    margin: 0;
    padding: 0;
}

.marketing-suggestions__card {
    position: relative;
    padding: 14px 16px 14px 18px;
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 10px;
    border-left-width: 3px;
}

.marketing-suggestions__card--critical {
    border-left-color: rgba(232, 95, 95, 0.85);
    background: linear-gradient(
        155deg,
        rgba(232, 95, 95, 0.08) 0%,
        rgba(255, 255, 255, 0.015) 70%
    );
}

.marketing-suggestions__card--high {
    border-left-color: rgba(210, 165, 80, 0.85);
    background: linear-gradient(
        155deg,
        rgba(210, 165, 80, 0.07) 0%,
        rgba(255, 255, 255, 0.015) 70%
    );
}

.marketing-suggestions__card--medium {
    border-left-color: rgba(130, 175, 220, 0.85);
    background: linear-gradient(
        155deg,
        rgba(130, 175, 220, 0.05) 0%,
        rgba(255, 255, 255, 0.015) 70%
    );
}

.marketing-suggestions__card--low {
    border-left-color: rgba(160, 160, 170, 0.6);
}

.marketing-suggestions__card-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
    margin-bottom: 6px;
}

.marketing-suggestions__severity {
    display: inline-flex;
    align-items: center;
    padding: 2px 8px;
    font-size: 0.66rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border-radius: 999px;
    border: 1px solid currentColor;
    line-height: 1.4;
}

.marketing-suggestions__severity--critical {
    color: rgba(255, 180, 180, 0.95);
    background: rgba(232, 95, 95, 0.12);
}

.marketing-suggestions__severity--high {
    color: rgba(255, 225, 170, 0.95);
    background: rgba(210, 165, 80, 0.14);
}

.marketing-suggestions__severity--medium {
    color: rgba(190, 220, 245, 0.95);
    background: rgba(130, 175, 220, 0.12);
}

.marketing-suggestions__severity--low {
    color: rgba(200, 200, 210, 0.85);
    background: rgba(255, 255, 255, 0.04);
}

.marketing-suggestions__card-title {
    margin: 0;
    font-size: 0.92rem;
    font-weight: 600;
    color: rgba(240, 232, 210, 0.96);
    line-height: 1.35;
}

.marketing-suggestions__card-body {
    margin: 0 0 10px;
    font-size: 0.84rem;
    line-height: 1.5;
    color: rgba(200, 200, 210, 0.92);
}

.marketing-suggestions__card-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 12px;
}

.marketing-suggestions__cta {
    display: inline-flex;
    align-items: center;
    padding: 7px 14px;
    font-size: 0.82rem;
    font-weight: 600;
    color: rgba(20, 18, 12, 0.96);
    background: linear-gradient(
        155deg,
        rgba(216, 181, 106, 0.96) 0%,
        rgba(184, 141, 60, 0.96) 100%
    );
    border-radius: 7px;
    text-decoration: none;
    transition: filter 120ms ease, transform 120ms ease;
}

.marketing-suggestions__cta:hover,
.marketing-suggestions__cta:focus-visible {
    filter: brightness(1.07);
    text-decoration: none;
}

.marketing-suggestions__cta:focus-visible {
    outline: 2px solid rgba(255, 225, 170, 0.85);
    outline-offset: 2px;
}

.marketing-suggestions__snooze {
    padding: 6px 10px;
    font-size: 0.76rem;
    font-family: inherit;
    color: rgba(200, 200, 210, 0.86);
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 7px;
    cursor: pointer;
    transition: border-color 120ms ease, color 120ms ease, background 120ms ease;
}

.marketing-suggestions__snooze:hover,
.marketing-suggestions__snooze:focus-visible {
    border-color: rgba(255, 255, 255, 0.32);
    color: rgba(240, 240, 245, 0.96);
    background: rgba(255, 255, 255, 0.04);
}

.marketing-suggestions__snooze:focus-visible {
    outline: 2px solid rgba(160, 160, 170, 0.6);
    outline-offset: 2px;
}

.marketing-suggestions__evidence {
    margin-top: 10px;
    font-size: 0.76rem;
    color: rgba(160, 160, 170, 0.9);
}

.marketing-suggestions__evidence summary {
